            required = {"rule", "source", "origin"} if is_ref else {"rule", "kind", "source", "origin"}
            optional = {"id", "note", "class", "perf_intent"} | ({"kind"} if is_ref else set())
            if not _keys_ok(item, required, optional, iw, errors):
